editorial:
Start at the widest pair. If the left height is smaller, every narrower pair that still uses the same left endpoint is bounded by that height and a smaller width. Discard it. The symmetric rule applies to the right endpoint, including when heights tie. Use 64-bit area. Time O(n), auxiliary space O(1) besides the input.
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; cin>>n;
    vector<long long>a(n);
    for (auto& x:a) cin>>x;
    long long best=0;
    for (int l=0,r=n-1;l<r;) {
        best=max(best,(r-l)*min(a[l],a[r]));
        if (a[l]<=a[r]) ++l;
        else --r;
    }
    cout<<best<<'\n';
}
